SET @TENANT = 'mocasa-ph';
SELECT COALESCE(MAX(config_version), 0) + 1 INTO @CFG_VER FROM t_contact_plan_template WHERE tenant_id = @TENANT;

UPDATE t_contact_plan_template
   SET plan_json = CAST('{"dayBlocks":[{"slots":[{"time":"08:00","channel":"SMS","observeMin":0,"templateId":101},{"time":"12:00","channel":"PUSH","observeMin":0,"templateId":102},{"time":"14:00","channel":"EMAIL","observeMin":0,"templateId":203}],"dpdDay":1},{"slots":[{"time":"08:00","channel":"SMS","observeMin":0,"templateId":101},{"time":"12:00","channel":"PUSH","observeMin":0,"templateId":102}],"dpdDay":2},{"slots":[{"time":"08:00","channel":"SMS","observeMin":0,"templateId":101},{"time":"12:00","channel":"PUSH","observeMin":0,"templateId":102}],"dpdDay":3}]}' AS JSON),
       config_version = @CFG_VER,
       version = version + 1,
       updated_by = 'pilot-ai-call-strip'
 WHERE template_code = 'PH1_S1_STANDARD' AND tenant_id = @TENANT;

